  ctx,
  _canvas,
  _config,
  state,
  trackIndex,
  eventIndex,
  eventX,
  trackY,
  eventWidth,
  eventVerticalPadding,
  eventHeight
) => {
  const event = state.tracks[trackIndex].events[eventIndex];
  if (!event.customData?.badge) return;

  ctx.save();
  ctx.fillStyle = "#fff";
  ctx.fillText(
    String(event.customData.badge),
    eventX + 8,
    trackY + eventVerticalPadding + eventHeight / 2
